INSERT INTO `wp_options` (`option_id`, `option_name`, `option_value`, `autoload`) VALUES
(1924, 'trustindex-google-review-content', '<div class=\" ti-widget \" data-layout-id=\"4\" data-layout-category=\"slider\" data-set-id=\"\" data-pid=\"\" data-language=\"en\" data-close-locale=\"Close\" data-review-target-width=\"300\" data-css-version=\"2\" data-review-text-mode=\"readmore\" data-reply-by-locale=\"Owner\'s reply\" data-only-rating-locale=\"This user only left a rating.\" data-pager-autoplay-timeout=\"6\" > <div class=\"ti-widget-container ti-col-3\"> <div class=\"ti-reviews-container\"> <div class=\"ti-controls\"> <div class=\"ti-next\" aria-label=\"Next review\" role=\"button\" tabindex=\"0\"></div> <div class=\"ti-prev\" aria-label=\"Previous review\" role=\"button\" tabindex=\"0\"></div> </div> <div class=\"ti-reviews-container-wrapper\"> <!-- R-LIST --> <div class=\"ti-review-item source-%platform% ti-image-layout-thumbnail\" data-platform-page-url=\"\" data-time=\"\" data-id=\"cfcd208495d565ef66e7dff9f98764da\" data-language=\"\" data-rating=\"5\" data-max-rating=\"5\" > <div class=\"ti-inner\"> <div class=\"ti-review-header\"> <div class=\"ti-platform-icon ti-with-tooltip\"> <span class=\"ti-tooltip\">Posted on %platform%</span> <img src=\"https://cdn.trustindex.io/assets/platform/%platform%/icon.svg\" alt=\"%platform%\" width=\"20\" height=\"20\" loading=\"lazy\" /> </div> <div class=\"ti-profile-img\"> <img src=\"%reviewer_photo%\" srcset=\"%reviewer_photo% 2x\" alt=\"%reviewer_name% profile picture\" loading=\"lazy\" /> </div> <div class=\"ti-profile-details\"> <div class=\"ti-name\"> %reviewer_name% </div> <div class=\"ti-date\">%created_at%</div> </div> </div> <span class=\"ti-stars\"><!-- STARS-CONTENT --></span> <div class=\"ti-review-text-container ti-review-content\"><!-- R-CONTENT -->%text%<!-- R-CONTENT --></div> <span class=\"ti-read-more\" data-container=\".ti-review-content\" data-collapse-text=\"Hide\" data-open-text=\"Read more\" ></span> </div> </div> <!-- R-LIST --> </div> <div class=\"ti-controls-line\"> <div class=\"dot\"></div> </div> </div> <div class=\"ti-footer\"> <div class=\"ti-rating-text\"> <span class=\"nowrap\"><strong>PLATFORM_NAME</strong> rating score: </span><span class=\"nowrap\"><strong>RATING_SCORE</strong> of RATING_SCALE, </span><span class=\"nowrap\">based on <strong>RATING_NUMBER reviews</strong></span><!-- FOOTER FILTER TEXT --> </div> </div> <div class=\"ti-footer-filter-text\"><!-- FOOTER FILTER TEXT --></div> <!-- VERIFIED BY TRUSTINDEX START<div class=\"ti-verified-by ti-verified-by-row\" data-style=\"1\"> <div class=\"ti-inner\"> Verified by Trustindex <span class=\"ti-info-icon\"></span> <div class=\"ti-disclaimer\">Trustindex verified badge is the Universal Symbol of Trust. Only the greatest companies can get the verified badge who has a review score above 4.5, based on customer reviews over the past 12 months. <a href=\"https://www.trustindex.io/?a=sys&c=verified-badge&url=/the-trustindex-verified-badge/\" target=\"_blank\">Read more</a></div> </div> </div> VERIFIED BY TRUSTINDEX END --> </div> </div> ', 'off'),
(1925, 'trustindex-google-widget-setted-up', '1', 'off'),
