(2013, '_transient_wpseo_task_list_tasks', '{\n    \"complete-ftc\": {\n        \"id\": \"complete-ftc\",\n        \"duration\": 15,\n        \"priority\": \"high\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Start configuration\",\n            \"type\": \"link\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/admin.php?page=wpseo_dashboard&wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f#\\/first-time-configuration\"\n        },\n        \"title\": \"Complete the first time configuration\",\n        \"about\": \"<p>Skipping setup limits how much Yoast SEO can help you. Completing it makes sure the core settings are working in your favor.<\\/p>\"\n    },\n    \"create-new-content\": {\n        \"id\": \"create-new-content\",\n        \"duration\": 90,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": false,\n        \"callToAction\": {\n            \"label\": \"Create new post\",\n            \"type\": \"add\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/post-new.php?wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f\"\n        },\n        \"title\": \"Create new content\",\n        \"about\": \"<p>Long gaps without new content slow down your traffic growth. Publishing regularly gives search engines and visitors a reason to return.<\\/p><p>Plan a topic, write your post, and use the Yoast SEO and Readability Analyses to refine it before publishing.<\\/p>\"\n    },\n    \"delete-hello-world\": {\n        \"id\": \"delete-hello-world\",\n        \"duration\": 1,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Delete for me\",\n            \"type\": \"delete\",\n            \"href\": null\n        },\n        \"title\": \"Remove the “Hello World” post\",\n        \"about\": \"<p>Leaving placeholder content makes your site look unfinished and untrustworthy. Removing it keeps your site clean and professional for visitors and search engines.<\\/p>\"\n    },\n    \"delete-sample-page\": {\n        \"id\": \"delete-sample-page\",\n        \"duration\": 1,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Delete for me\",\n            \"type\": \"delete\",\n            \"href\": null\n        },\n        \"title\": \"Remove the \\\"Sample Page\\\"\",\n        \"about\": \"<p>Leaving placeholder content makes your site look unfinished and untrustworthy. Removing it keeps your site clean and professional for visitors and search engines.<\\/p>\"\n    },\n    \"enable-llms-txt\": {\n        \"id\": \"enable-llms-txt\",\n        \"duration\": 1,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Enable llms.txt\",\n            \"type\": \"default\",\n            \"href\": null\n        },\n        \"title\": \"Create an llms.txt file\",\n        \"about\": \"<p>Without llms.txt, AI platforms may not know how to treat your content. Enabling it helps communicate your preferences in a clearer way to AI tools.<\\/p>\"\n    },\n    \"improve-content-readability-post\": {\n        \"id\": \"improve-content-readability-post\",\n        \"duration\": 0,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": null,\n        \"title\": \"Improve the readability of your recent content: Posts\",\n        \"about\": \"<p>Checking your recent content\'s readability ensures it stays clear and easy to follow, improving your user experience. Follow the feedback to refine your sentence structure and word choice and maintain a high standard of engagement and comprehension.<\\/p><p><strong>Pro tip<\\/strong>: Use <strong>AI Optimize<\\/strong> to automatically simplify complex sentences and improve the flow of your writing.<\\/p>\",\n        \"isParentTask\": true\n    },\n    \"improve-content-readability-page\": {\n        \"id\": \"improve-content-readability-page\",\n        \"duration\": 0,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": null,\n        \"title\": \"Improve the readability of your recent content: Pages\",\n        \"about\": \"<p>Checking your recent content\'s readability ensures it stays clear and easy to follow, improving your user experience. Follow the feedback to refine your sentence structure and word choice and maintain a high standard of engagement and comprehension.<\\/p><p><strong>Pro tip<\\/strong>: Use <strong>AI Optimize<\\/strong> to automatically simplify complex sentences and improve the flow of your writing.<\\/p>\",\n        \"isParentTask\": true\n    },\n    \"improve-content-seo-post\": {\n        \"id\": \"improve-content-seo-post\",\n        \"duration\": 0,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": null,\n        \"title\": \"Improve the SEO of your recent content: Posts\",\n        \"about\": \"<p>By aligning your content with search intent and focus keyphrases, you make it easier for people and AI systems to find your website, improving your organic visibility. Use the recommendations in the SEO analysis to strengthen your technical performance and ranking potential.<\\/p><p><strong>Pro tip<\\/strong>: Use <strong>AI Generate<\\/strong> to quickly generate high quality meta descriptions and keyphrase-rich headers that rank well.<\\/p>\",\n        \"isParentTask\": true\n    },\n    \"improve-content-seo-page\": {\n        \"id\": \"improve-content-seo-page\",\n        \"duration\": 0,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": null,\n        \"title\": \"Improve the SEO of your recent content: Pages\",\n        \"about\": \"<p>By aligning your content with search intent and focus keyphrases, you make it easier for people and AI systems to find your website, improving your organic visibility. Use the recommendations in the SEO analysis to strengthen your technical performance and ranking potential.<\\/p><p><strong>Pro tip<\\/strong>: Use <strong>AI Generate<\\/strong> to quickly generate high quality meta descriptions and keyphrase-rich headers that rank well.<\\/p>\",\n        \"isParentTask\": true\n    },\n    \"improve-default-meta-descriptions-post\": {\n        \"id\": \"improve-default-meta-descriptions-post\",\n        \"duration\": 0,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": null,\n        \"title\": \"Improve default meta descriptions of your recent content: Posts\",\n        \"about\": \"<p>Default meta descriptions don\'t always highlight what makes your page unique. Write your own to improve clarity and drive more clicks.<\\/p><p>Short on time? In <strong>Yoast SEO Premium<\\/strong>, use <strong>AI Generate<\\/strong> to create tailored meta descriptions in seconds.<\\/p>\",\n        \"isParentTask\": true\n    },\n    \"improve-default-meta-descriptions-page\": {\n        \"id\": \"improve-default-meta-descriptions-page\",\n        \"duration\": 0,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": null,\n        \"title\": \"Improve default meta descriptions of your recent content: Pages\",\n        \"about\": \"<p>Default meta descriptions don\'t always highlight what makes your page unique. Write your own to improve clarity and drive more clicks.<\\/p><p>Short on time? In <strong>Yoast SEO Premium<\\/strong>, use <strong>AI Generate<\\/strong> to create tailored meta descriptions in seconds.<\\/p>\",\n        \"isParentTask\": true\n    },\n    \"improve-content-readability-page-34\": {\n        \"id\": \"improve-content-readability-page-34\",\n        \"duration\": 10,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Improve readability\",\n            \"type\": \"link\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/post.php?post=34&action=edit&yoast-tab=readability&wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f\"\n        },\n        \"title\": \"Privacy Policy\",\n        \"about\": \"<p>Checking your recent content\'s readability ensures it stays clear and easy to follow, improving your user experience. Follow the feedback to refine your sentence structure and word choice and maintain a high standard of engagement and comprehension.<\\/p><p><strong>Pro tip<\\/strong>: Use <strong>AI Optimize<\\/strong> to automatically simplify complex sentences and improve the flow of your writing.<\\/p>\",\n        \"parentTaskId\": \"improve-content-readability-page\",\n        \"analyzer\": {\n            \"type\": \"score\",\n            \"title\": \"Readability\",\n            \"result\": \"good\",\n            \"resultLabel\": \"Good\",\n            \"resultDescription\": \"Your content is clear and easy to read. This helps your audience stay engaged with your message.\"\n        }\n    },\n    \"improve-content-readability-page-19\": {\n        \"id\": \"improve-content-readability-page-19\",\n        \"duration\": 10,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Improve readability\",\n            \"type\": \"link\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/post.php?post=19&action=edit&yoast-tab=readability&wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f\"\n        },\n        \"title\": \"Home\",\n        \"about\": \"<p>Checking your recent content\'s readability ensures it stays clear and easy to follow, improving your user experience. Follow the feedback to refine your sentence structure and word choice and maintain a high standard of engagement and comprehension.<\\/p><p><strong>Pro tip<\\/strong>: Use <strong>AI Optimize<\\/strong> to automatically simplify complex sentences and improve the flow of your writing.<\\/p>\",\n        \"parentTaskId\": \"improve-content-readability-page\",\n        \"analyzer\": {\n            \"type\": \"score\",\n            \"title\": \"Readability\",\n            \"result\": \"good\",\n            \"resultLabel\": \"Good\",\n            \"resultDescription\": \"Your content is clear and easy to read. This helps your audience stay engaged with your message.\"\n        }\n    },\n    \"improve-content-readability-page-36\": {\n        \"id\": \"improve-content-readability-page-36\",\n        \"duration\": 10,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Improve readability\",\n            \"type\": \"link\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/post.php?post=36&action=edit&yoast-tab=readability&wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f\"\n        },\n        \"title\": \"Sitemap\",\n        \"about\": \"<p>Checking your recent content\'s readability ensures it stays clear and easy to follow, improving your user experience. Follow the feedback to refine your sentence structure and word choice and maintain a high standard of engagement and comprehension.<\\/p><p><strong>Pro tip<\\/strong>: Use <strong>AI Optimize<\\/strong> to automatically simplify complex sentences and improve the flow of your writing.<\\/p>\",\n        \"parentTaskId\": \"improve-content-readability-page\",\n        \"analyzer\": {\n            \"type\": \"score\",\n            \"title\": \"Readability\",\n            \"result\": \"good\",\n            \"resultLabel\": \"Good\",\n            \"resultDescription\": \"Your content is clear and easy to read. This helps your audience stay engaged with your message.\"\n        }\n    },\n    \"improve-default-meta-descriptions-page-34\": {\n        \"id\": \"improve-default-meta-descriptions-page-34\",\n        \"duration\": 5,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Open editor\",\n            \"type\": \"link\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/post.php?post=34&action=edit&wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f\"\n        },\n        \"title\": \"Privacy Policy\",\n        \"about\": \"<p>Default meta descriptions don\'t always highlight what makes your page unique. Write your own to improve clarity and drive more clicks.<\\/p><p>Short on time? In <strong>Yoast SEO Premium<\\/strong>, use <strong>AI Generate<\\/strong> to create tailored meta descriptions in seconds.<\\/p>\",\n        \"parentTaskId\": \"improve-default-meta-descriptions-page\",\n        \"analyzer\": null\n    },\n    \"improve-default-meta-descriptions-page-19\": {\n        \"id\": \"improve-default-meta-descriptions-page-19\",\n        \"duration\": 5,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Open editor\",\n            \"type\": \"link\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/post.php?post=19&action=edit&wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f\"\n        },\n        \"title\": \"Home\",\n        \"about\": \"<p>Default meta descriptions don\'t always highlight what makes your page unique. Write your own to improve clarity and drive more clicks.<\\/p><p>Short on time? In <strong>Yoast SEO Premium<\\/strong>, use <strong>AI Generate<\\/strong> to create tailored meta descriptions in seconds.<\\/p>\",\n        \"parentTaskId\": \"improve-default-meta-descriptions-page\",\n        \"analyzer\": null\n    },\n    \"improve-default-meta-descriptions-page-36\": {\n        \"id\": \"improve-default-meta-descriptions-page-36\",\n        \"duration\": 5,\n        \"priority\": \"medium\",\n        \"badge\": null,\n        \"isCompleted\": true,\n        \"callToAction\": {\n            \"label\": \"Open editor\",\n            \"type\": \"link\",\n            \"href\": \"https:\\/\\/localhost\\/ustbs26\\/wp-admin\\/post.php?post=36&action=edit&wpseo_tracked_action=task_first_actioned_on&wpseo_tracking_nonce=50bedc0e8f\"\n        },\n        \"title\": \"Sitemap\",\n        \"about\": \"<p>Default meta descriptions don\'t always highlight what makes your page unique. Write your own to improve clarity and drive more clicks.<\\/p><p>Short on time? In <strong>Yoast SEO Premium<\\/strong>, use <strong>AI Generate<\\/strong> to create tailored meta descriptions in seconds.<\\/p>\",\n        \"parentTaskId\": \"improve-default-meta-descriptions-page\",\n        \"analyzer\": null\n    }\n}', 'off'),
